CREATE TABLE dbo.T (Id int NOT NULL CONSTRAINT PK_T PRIMARY KEY, Tenant int NOT NULL)
GO
CREATE FUNCTION dbo.TenantFilter (@Tenant int) RETURNS TABLE WITH SCHEMABINDING AS RETURN SELECT 1 AS ok WHERE @Tenant = 1
GO
CREATE SECURITY POLICY dbo.TenantPolicy ADD FILTER PREDICATE dbo.TenantFilter(Tenant) ON dbo.T WITH (STATE = ON)
